bool near(float a,float b){return re::re_fabs(a-b)<0.00001f;}
FontTextGlyph glyph(ReU16 cp,float advance=4){return {(ReU32(cp)<<2)|2,advance,0,0,4,8,0,0,1,1};}
FontTextFont fixture(){FontTextFont f;f.measure.nominal=8;f.fallback_character='?';f.glyphs={glyph(' '),glyph('?'),glyph('A'),glyph('.'),glyph(0x2026)};f.ellipsis_step=7;font_text_build_lookup_3a33c0(f);return f;}
float field(const DrawVertex& v,ReUSize offset){float f;re::re_memcpy(&f,v.data()+offset,4);return f;}
ReU32 color(const DrawVertex& v){ReU32 x;re::re_memcpy(&x,v.data()+16,4);return x;}
